import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

// ── S5 — the defect class is regenerated by its surroundings ─────────────────
//
// Ten commands constructed `new SqliteEventStore(...)` directly, which made every operator
// diagnostic runnable only on the single-node backend — the one deployment the features they
// serve are NOT for. Converting them fixes today; without a guard the next command added goes
// straight back, because that is what every neighbouring file did.
//
// Sweeping a defect without fixing what regenerates it just resets the clock.

const SRC = __dirname;

/**
 * Files allowed to name a concrete backend, each for a stated reason. An allowlist with
 * reasons keeps the exception VISIBLE; a guard with silent holes is the vacuous-check pattern
 * wearing a green tick.
 */
const ALLOWED: Record<string, string> = {
  "sqlitePlugin.ts":
    "the one place that loads the optional @loomwork/plugin-sqlite peer; every SQLite user goes through loadSqlitePlugin()",
  "stores.ts": "the `--db` SQLite shorthand lives here, and only here",
  "sweepContent.ts":
    "`--content` and `--archive-db` are paths: defineConfig has no content-store seam, so there is nothing for --config to hand over",
};

function sourceFiles(): string[] {
  return readdirSync(SRC).filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts"));
}

describe("S5 — diagnostics resolve storage, they do not construct it", () => {
  it("no command names a concrete backend outside the allowlist", () => {
    const offenders = sourceFiles().filter((file) => {
      if (file in ALLOWED) return false;
      // The plugin is an optional peer loaded through `loadSqlitePlugin()`, so a call to it names
      // the backend as surely as an import does.
      return /@loomwork\/plugin-(sqlite|postgres)|loadSqlitePlugin/.test(
        readFileSync(join(SRC, file), "utf8")
      );
    });
    expect(offenders).toEqual([]);
  });

  it("the allowlist names files that exist — a stale exemption is a hole", () => {
    const present = new Set(sourceFiles());
    for (const file of Object.keys(ALLOWED)) expect(present.has(file)).toBe(true);
  });

  it("every allowlisted file states WHY, so the exception cannot drift into a habit", () => {
    for (const [file, reason] of Object.entries(ALLOWED)) {
      expect(reason.length, `${file} needs a reason`).toBeGreaterThan(20);
    }
  });
});
